package com.dawnrise.academic.security.internal;
import org.springframework.boot.context.properties.ConfigurationProperties;import org.springframework.beans.factory.InitializingBean;import java.util.*;
@ConfigurationProperties(prefix="security.internal") public class InternalServiceSecurityProperties implements InitializingBean {private String apiKey;private List<String> allowedServiceNames=new ArrayList<>();public String getApiKey(){return apiKey;}public void setApiKey(String v){apiKey=v;}public List<String> getAllowedServiceNames(){return allowedServiceNames;}public void setAllowedServiceNames(List<String> v){allowedServiceNames=v;}@Override public void afterPropertiesSet(){if(apiKey==null||apiKey.isBlank())throw new IllegalStateException("security.internal.api-key must be configured");if(allowedServiceNames==null||allowedServiceNames.stream().noneMatch(v->v!=null&&!v.isBlank()))throw new IllegalStateException("security.internal.allowed-service-names must include at least one service");}}
